# SPDX-License-Identifier: MIT
# Trusted fixture tooling: parse an $argon2id$ PHC string in either the
# standard PHC encoding (unpadded B64 salt and hash) or a lowercase-hex
# layout, and recompute its derived key with the independent argon2 CLI.
#   info PHC          -> "format=b64|hex|other" and "params=... salt-bytes=N hash-bytes=N"
#   oracle PHC FILE   -> "kdf=match|mismatch|salt-nul|unparsed" (password = FILE bytes)
#   salt PHC          -> salt bytes as hex
import base64, re, subprocess, sys

HEX = re.compile(r"^(?:[0-9a-f]{2})+$")
B64 = re.compile(r"^[A-Za-z0-9+/]+$")


def parse(phc):
    parts = phc.split("$")
    if len(parts) != 6 or parts[0] or parts[1] != "argon2id" or parts[2] != "v=19":
        return None
    kv = dict(item.split("=", 1) for item in parts[3].split(",") if "=" in item)
    try:
        m, t, p = int(kv["m"]), int(kv["t"]), int(kv["p"])
    except (KeyError, ValueError):
        return None
    salt, digest = parts[4], parts[5]
    if HEX.match(salt) and HEX.match(digest):
        return "hex", m, t, p, bytes.fromhex(salt), bytes.fromhex(digest)
    if B64.match(salt) and B64.match(digest):
        try:
            dec = lambda s: base64.b64decode(s + "=" * (-len(s) % 4), validate=True)
            return "b64", m, t, p, dec(salt), dec(digest)
        except ValueError:
            return None
    return None


mode, phc = sys.argv[1], sys.argv[2]
r = parse(phc)
if mode == "info":
    if not r:
        print("format=other")
        print("params=unparsed")
    else:
        print("format=" + r[0])
        print("params=m=%d,t=%d,p=%d salt-bytes=%d hash-bytes=%d" % (r[1], r[2], r[3], len(r[4]), len(r[5])))
elif mode == "salt":
    print(r[4].hex() if r else "unparsed")
elif mode == "oracle":
    if not r:
        print("kdf=unparsed")
    elif b"\0" in r[4]:
        print("kdf=salt-nul")
    else:
        pw = open(sys.argv[3], "rb").read()
        out = subprocess.run(["/usr/bin/argon2", r[4], "-id", "-t", str(r[2]), "-k", str(r[1]), "-p", str(r[3]),
                              "-l", str(len(r[5])), "-r"], input=pw, capture_output=True, check=True).stdout
        print("kdf=" + ("match" if out.strip().decode() == r[5].hex() else "mismatch"))
else:
    sys.exit(2)
